import { cookies, headers } from 'next/headers'

function getPreferredLanguage(acceptLanguage: string | null): string {
  if (!acceptLanguage) {
    return 'Not specified'
  }

  const preferred = acceptLanguage
    .split(',')
    .map((entry, index) => {
      const [language, ...params] = entry.trim().split(';')
      const qualityParam = params.find((param) => param.trim().startsWith('q='))
      const quality = qualityParam
        ? Number.parseFloat(qualityParam.trim().slice(2))
        : 1

      return {
        index,
        language: language.trim(),
        quality: Number.isFinite(quality) ? quality : 0,
      }
    })
    .filter(({ language }) => language.length > 0)
    .sort((a, b) => b.quality - a.quality || a.index - b.index)[0]

  return preferred?.language ?? 'Not specified'
}

export default async function UserPreferences() {
  const cookieStore = await cookies()
  const headersList = await headers()

  const theme = cookieStore.get('theme')?.value || 'light'
  const preferredLanguage = getPreferredLanguage(
    headersList.get('accept-language'),
  )

  return (
    <section>
      <h2>Current Preferences</h2>
      <p>Current theme preference: {theme}</p>
      <p>Preferred language: {preferredLanguage}</p>
    </section>
  )
}

